/**
 * A memória do DNA — porte de `componentes/viz/dna_dados.js`.
 *
 * Um grama de DNA guarda mais informação do que todos os data centers do mundo
 * juntos. O número é grande demais para significar alguma coisa dito em voz alta,
 * então a cena o encena: conforme a compactação sobe, a cidade de prédios de
 * servidores encolhe até caber numa gota.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** [x, largura, altura, é da fileira da frente] — frações de (L, A). */
const PREDIOS: readonly (readonly [number, number, number, boolean])[] = [
  [-0.21, 0.052, 0.3, false],
  [-0.135, 0.062, 0.4, false],
  [-0.05, 0.052, 0.28, false],
  [0.03, 0.062, 0.38, false],
  [0.11, 0.052, 0.32, false],
  [0.18, 0.05, 0.26, false],
  [-0.18, 0.072, 0.46, true],
  [-0.085, 0.085, 0.58, true],
  [0.01, 0.072, 0.42, true],
  [0.1, 0.066, 0.5, true],
  [0.18, 0.06, 0.36, true],
];

const dnaDados: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const compactacao = Math.max(0, numeroDe(valores, 'k', 0));
    const ok = info.ok === true;
    const f = compactacao / 100;

    titulo(ctx, L, A, 'Cabe tudo num punhado');

    // A cidade de servidores, encolhendo.
    const escala = 1 - f * 0.92;
    const campoX = L * 0.26;
    const campoY = A * 0.54;
    const chao = A * 0.27;

    ctx.save();
    ctx.translate(campoX, campoY);
    ctx.scale(escala, escala);
    ctx.globalAlpha = 0.5 + (1 - f) * 0.5;

    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-L * 0.26, chao);
    ctx.lineTo(L * 0.24, chao);
    ctx.stroke();

    for (let n = 0; n < PREDIOS.length; n++) {
      const predio = PREDIOS[n];
      if (predio === undefined) continue;
      const [xf, wf, hf, frente] = predio;

      const x = xf * L;
      const w = wf * L;
      const h = hf * A;
      const y = chao - h;

      ctx.fillStyle = frente ? '#4a6a8a' : '#33506e';
      ctx.fillRect(x, y, w, h);

      // As luzinhas dos racks — é o que faz o prédio ler como data center.
      ctx.fillStyle = frente ? '#8fe3ff' : '#5aa6cc';
      const colunas = Math.max(2, Math.round(w / 7));
      const linhas = Math.max(3, Math.round(h / 12));
      for (let i = 0; i < linhas; i++) {
        for (let j = 0; j < colunas; j++) {
          if (Math.sin(t * 3 + n + i * 1.7 + j) > 0.2) {
            ctx.fillRect(x + 3 + (j * (w - 5)) / colunas, y + 4 + (i * (h - 6)) / linhas, 2.5, 2.5);
          }
        }
      }
    }
    ctx.restore();
    ctx.globalAlpha = 1;

    texto(
      ctx,
      f < 0.5 ? 'data centers do mundo' : 'servidores',
      campoX,
      A * 0.86,
      limitar(A * 0.038, 9, 12),
      { cor: cor.fraco, peso: 700 },
    );

    // A seta da compactação.
    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(L * 0.44, A * 0.54);
    ctx.lineTo(L * 0.56, A * 0.54);
    ctx.moveTo(L * 0.56, A * 0.54);
    ctx.lineTo(L * 0.52, A * 0.5);
    ctx.moveTo(L * 0.56, A * 0.54);
    ctx.lineTo(L * 0.52, A * 0.58);
    ctx.stroke();

    // A gota e a hélice, que crescem no sentido contrário.
    const dx = L * 0.74;
    const dy = A * 0.54;
    const escalaDna = 0.5 + f * 0.9;

    ctx.fillStyle = `rgb(90 166 255 / ${(0.18 + f * 0.2) * 100}%)`;
    ctx.beginPath();
    ctx.ellipse(dx, dy + A * 0.04, 40 * escalaDna, 52 * escalaDna, 0, 0, Math.PI * 2);
    ctx.fill();

    const h = A * 0.32 * escalaDna;
    const w = 16 * escalaDna;
    ctx.lineWidth = 2.5;
    ctx.strokeStyle = ok ? cor.verde : cor.azul;
    for (const sentido of [1, -1]) {
      ctx.beginPath();
      for (let p = 0; p <= 1; p += 0.04) {
        const y = dy - h / 2 + p * h;
        const x = dx + Math.sin(p * Math.PI * 4 + t) * w * sentido;
        if (p === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }

    ctx.strokeStyle = ok ? cor.verde : cor.azulClaro;
    ctx.lineWidth = 1.5;
    for (let p = 0.05; p < 1; p += 0.1) {
      const y = dy - h / 2 + p * h;
      const x1 = dx + Math.sin(p * Math.PI * 4 + t) * w;
      const x2 = dx - Math.sin(p * Math.PI * 4 + t) * w;
      ctx.beginPath();
      ctx.moveTo(x1, y);
      ctx.lineTo(x2, y);
      ctx.stroke();
    }

    texto(ctx, '1 g de DNA', dx, dy + A * 0.04 + 56 * escalaDna + 8, limitar(A * 0.038, 9, 12), {
      cor: cor.fraco,
      peso: 700,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Toda a informação do mundo num punhado de DNA ✔',
      `Compactação ${Math.round(compactacao)}% — ainda ocupa prédios.`,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default dnaDados;
